@js:
var JsDom = Packages.org.jsoup.Jsoup;
var Document = Packages.org.jsoup.nodes.Document;
var Element = Packages.org.jsoup.nodes.Element;

var document = JsDom.parse(src);

var png = /next.png/.test(src);
var matchResult = src.match(/eval(.function.*)/);
var next = matchResult ? matchResult[1] : "";
var url = next ? eval(next) : "";
java.log(url);

if (url) {

    var nextChapterElement = document.select("*:contains(下一章)").first();

    if (nextChapterElement) {
        java.log("找到下一章，停止执行。");
    } else {
        eval(url.replace(/var/, ""));
    }
}

exploreUrl:
@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://www3.longtimebook.com/category/";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".CGsectionTwo-left p span a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 0; i < a.length ; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/$/,'{{page}}.html');      
        push(title, url, size);
    }
} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);

